mapper.select:
select 
from oa_sign_onboard_import_batch b
where b.shop_dept_id = #{shopDeptId}
  and b.created_by_user_id = #{createdByUserId}
  and b.selection_hash = #{selectionHash}
  and b.file_sha256 = #{fileSha256}
  and b.expires_time > #{now}
  and b.status in ('PREVIEW_READY', 'PARTIAL_GENERATED', 'GENERATED')
  and not exists (
      select 1
      from oa_sign_onboard_import_row r
      where r.batch_id = b.batch_id
        and r.status in ('PLAN_CHANGED_REPREVIEW', 'PROFILE_CHANGED_REPREVIEW',
                         'PROFILE_SYNC_FAILED')
  )
order by b.batch_id desc
limit 1

select distinct b.batch_id
from oa_sign_onboard_import_batch b
inner join oa_sign_onboard_import_row r on r.batch_id = b.batch_id
where b.status = 'GENERATING'
  and b.update_time <= #{staleBefore}
  and r.status = 'GENERATING'
  and r.update_time <= #{staleBefore}
order by b.batch_id asc
limit #{maxRows}

mapper.update:
update oa_sign_onboard_import_batch
set status = 'GENERATING', version = version + 1, update_time = sysdate()
where batch_id = #{batchId}
  and version = #{expectedVersion}
  and (
      status in ('PREVIEW_READY', 'PARTIAL_GENERATED', 'GENERATED')
      or (status = 'GENERATING' and update_time <= #{staleBefore})
  )
